from pathlib import Path
import json
import pandas as pd
from src.pipeline import policy_selection
ROOT=Path(__file__).resolve().parent
summary=json.loads((ROOT/'outputs/summary.json').read_text())
d=pd.read_csv(ROOT/'outputs/out_of_time_predictions.csv')
fixed=[]
for label,method in [('Random eligible','random'),('Highest risk','risk'),('Greedy value-first','value')]:
    sel=policy_selection(d,650,method)
    fixed.append({'name':label,'contacts':len(sel),'riskExposure':round(float((sel.p30*sel.ead_usd).sum()),4)})
m=summary['metrics']
html=r'''<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Credtr.ai, an independent synthetic-data credit early-warning and scenario economics portfolio project"><title>Credtr.ai — Credit Strategy Decision Lab</title>
<style>
:root{--navy:#102a46;--blue:#3169d6;--ink:#18283b;--muted:#63758c;--line:#e2e9f3;--bg:#f5f7fb;--card:#fff;--warn:#fff5e6;--accent:#017e78}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink);line-height:1.55}header{background:linear-gradient(110deg,#102a46,#164a72);color:white;padding:52px max(20px,calc((100vw - 1050px)/2));}header h1{font-size:clamp(2rem,5vw,3.3rem);letter-spacing:-.04em;margin:6px 0}header p{max-width:720px;color:#d1e4f4}.pill{border:1px solid #7793b6;color:#e1ecf6;border-radius:30px;padding:5px 12px;font-size:12px;display:inline-block;margin-right:8px}.container{max-width:1100px;padding:24px 20px 65px;margin:auto}.notice{padding:14px 17px;background:var(--warn);border-left:4px solid #ce8a19;border-radius:8px;font-size:14px;margin-bottom:24px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px}.card{background:var(--card);border:1px solid var(--line);border-radius:13px;padding:23px;box-shadow:0 4px 18px #1d385208}.value{font-size:30px;font-weight:780;color:#123452;letter-spacing:-.03em}.label{font-size:13px;color:var(--muted);font-weight:600}section{margin-top:30px}h2{font-size:22px;margin:0 0 14px}h3{font-size:17px;margin:4px 0 8px}.two{display:grid;grid-template-columns:1.05fr .95fr;gap:20px}.architecture{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.architecture span{padding:12px 14px;background:#eef5fd;border:1px solid #cfe0f5;border-radius:9px;font-size:14px;font-weight:650}.architecture b{color:var(--blue)}.barrow{margin:17px 0}.barhead{display:flex;justify-content:space-between;gap:10px;font-size:13px}.bartrack{height:11px;background:#edf1f7;border-radius:30px;overflow:hidden;margin-top:6px}.barfill{height:100%;background:#557ec6;border-radius:30px;transition:width .2s}.barfill.best{background:var(--accent)}.controls{display:grid;grid-template-columns:1fr 1fr;gap:14px}.controls label{font-weight:650;font-size:13px;display:block}.controls output{float:right;color:var(--blue)}input[type=range]{width:100%;accent-color:var(--blue);margin-top:9px}.table{width:100%;border-collapse:collapse;font-size:14px}.table th{text-align:left;color:#64748b;padding:12px 10px;background:#f4f7fb}.table td{padding:12px 10px;border-top:1px solid var(--line)}.foot{font-size:13px;color:var(--muted)}.highlight{font-weight:720;color:var(--accent)}a{color:#1961b8}footer{margin-top:35px;border-top:1px solid var(--line);padding-top:16px;color:var(--muted);font-size:12px}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.two,.controls{grid-template-columns:1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr 1fr}.card{padding:16px}.value{font-size:24px}}
</style></head>
<body>
<header><span class="pill">Financial Services Analytics</span><span class="pill">100% synthetic, reproducible</span><h1>Credtr.ai</h1><p>From early-warning risk models to explainable, operationally feasible portfolio decisions. A master's-level independent analytics case study combining machine learning, economic constraints, and accountable leadership.</p></header>
<main class="container">
<div class="notice"><strong>Educational simulation — no banking customer data.</strong> Outcome is 30+ days past due within 60 days, <em>not</em> probability of default. No live credit decisions, no actual TCS client work, and no demonstrated loss savings. Results below are synthetic model evaluation and hypothetical financial scenarios.</div>
<div class="grid"><div class="card"><div class="label">Test observations</div><div class="value">15,200</div><div class="foot">4 monthly account snapshots</div></div><div class="card"><div class="label">Gradient-boosting AUC</div><div class="value">0.800</div><div class="foot">Time-held-out evaluation</div></div><div class="card"><div class="label">Logistic regression AUC</div><div class="value">0.804</div><div class="foot">A simpler challenger wins on test</div></div><div class="card"><div class="label">Top-decile event capture</div><div class="value">39.1%</div><div class="foot">For selected boosted model</div></div></div>
<section class="card"><h2>Decision architecture</h2><div class="architecture"><span>Account-month snapshots</span><b>→</b><span>SQL & hypothesis analysis</span><b>→</b><span>Rules / Logistic / AI challenger</span><b>→</b><span>Temporal calibration & validation</span><b>→</b><span>Human-reviewed outreach policy</span><b>→</b><span>Scenario economics + experiment</span></div><p class="foot">Important: the model predicts delinquency risk, not the counterfactual benefit of contacting a customer. Such benefit requires ethically approved experiments.</p></section>
<section class="two"><article class="card"><h2>What the model actually learned</h2><p>Prior missed payments, payment behavior, utilization changes, and other synthetic pre-snapshot behavioral signals support predictions of future 30+ DPD. Correlation is not proof of causation.</p><p><strong>The surprising model result:</strong> gradient boosting narrowly wins validation PR AUC, but logistic regression performs slightly better on the untouched test. That fails to establish an economically meaningful case for model complexity.</p><p><strong>Decision:</strong> do not deploy a more complex model merely because it is called AI. Require fresh independent validation before any live trial.</p></article><article class="card"><h2>Human and operating constraints</h2><p>Eligible outreach excludes synthetic opt-outs and open disputes, limits contact frequency, and enforces a 60-day scenario cooldown on repeat selections.</p><p>The modeled portfolio has a maximum team capacity of 650 contacts per month, but the cooldown may keep utilization below that ceiling.</p><p><strong>Permitted purpose:</strong> supportive, risk-approved information and assistance. Not credit limit changes, price increases, underwriting, or adverse credit actions.</p></article></section>
<section class="two"><article class="card"><h2>Scenario economics</h2><p class="foot">Change the assumptions below. Strategy cohorts remain frozen at the base-case selection; reranking would require running the Python dashboard. Dollars are scenario values, not measured savings.</p>
<div class="controls">
<div><label for="transition">Progression to loss <output id="transitionOut">25%</output></label><input id="transition" type="range" min="5" max="60" step="5" value="25"></div>
<div><label for="lgd">Loss given default <output id="lgdOut">70%</output></label><input id="lgd" type="range" min="20" max="90" step="5" value="70"></div>
<div><label for="effect">Hypothetical outreach effect <output id="effectOut">16%</output></label><input id="effect" type="range" min="0" max="35" step="1" value="16"></div>
<div><label for="cost">Cost per outreach <output id="costOut">$8.50</output></label><input id="cost" type="range" min="0" max="30" step="0.5" value="8.5"></div></div>
<div id="bars" aria-live="polite"></div></article>
<article class="card"><h2>What decision does the evidence support?</h2><div class="value" id="bestName" style="font-size:22px">Calculating…</div><p class="highlight" id="bestValue"></p><p id="comparison"></p><p>Because a 60-day contact cooldown affects who remains available in subsequent months, a per-month value-ranked <em>greedy</em> heuristic is not guaranteed to maximize four-month value. A strong analyst tests this rather than assuming it.</p><p><strong>Approval gate:</strong> estimate actual intervention efficacy using a randomized, compliant supportive-outreach pilot. Stop if harm, calibration, or economic guardrails fail.</p></article></section>
<section class="card"><h2>Model challenge: why the simpler option matters</h2><table class="table"><thead><tr><th>Model</th><th>ROC AUC</th><th>PR AUC</th><th>Brier ↓</th><th>Top 10% event capture</th></tr></thead><tbody>
<tr><td>Risk flags</td><td>0.756</td><td>0.306</td><td>0.084</td><td>36.2%</td></tr>
<tr><td>Logistic regression</td><td>0.804</td><td>0.393</td><td>0.080</td><td>39.7%</td></tr>
<tr><td>Gradient-boosted AI</td><td>0.800</td><td>0.389</td><td>0.080</td><td>39.1%</td></tr>
</tbody></table><p class="foot">All reported results are from the same synthetic time-held-out test. The boosted model was selected using a separate earlier validation period; these test figures are a stop/challenge gate, not permission to optimize repeatedly on the test set.</p></section>
<section class="card"><h2>Next decisions and risk governance</h2><ol><li><strong>Validate.</strong> Confirm as-of features, calibration, outcome definitions, independent model-review requirements, and permitted use.</li><li><strong>Shadow test.</strong> Record prediction quality and operational feasibility without customer impacts.</li><li><strong>Experiment.</strong> Use an approved, ethically permissible randomized supportive-communication trial to estimate causal effects.</li><li><strong>Assess economics.</strong> Count actual outreach costs, complaints, uncertainty, capacity, conversion to severe delinquency, and any causal benefit.</li><li><strong>Scale, simplify, or stop.</strong> Favor the simplest validated strategy that improves customer and portfolio outcomes.</li></ol>
<p class="foot">Further reading: <a href="https://www.bankofengland.co.uk/prudential-regulation/publication/2023/may/model-risk-management-principles-for-banks-ss">UK PRA SS1/23</a> (check applicability), <a href="https://airc.nist.gov/airmf-resources/playbook/">NIST AI RMF Playbook</a>, <a href="https://scikit-learn.org/stable/modules/calibration.html">Probability calibration documentation</a>.</p></section>
<footer>Credtr.ai © Independent portfolio demonstration. No real bank data, actual credit losses, realized treatment effects, or live automated credit decisions. To deploy: enable GitHub Pages with source <strong>main /docs</strong>.</footer>
</main><script>
const rows=__ROWS__;
const fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const ids=['transition','lgd','effect','cost'];
function update(){const [tr,lg,ef,ct]=ids.map(x=>Number(document.getElementById(x).value));document.getElementById('transitionOut').textContent=tr+'%';document.getElementById('lgdOut').textContent=lg+'%';document.getElementById('effectOut').textContent=ef+'%';document.getElementById('costOut').textContent='$'+ct.toFixed(2);
const values=rows.map(r=>({...r,net:r.riskExposure*tr/100*lg/100*ef/100-r.contacts*ct})); const max=Math.max(1,...values.map(v=>Math.max(0,v.net)));let html='';for(const v of values){html+=`<div class="barrow"><div class="barhead"><strong>${v.name}</strong><span>${fmt(v.net)} · ${v.contacts.toLocaleString()} contacts</span></div><div class="bartrack"><div class="barfill ${v.net===Math.max(...values.map(z=>z.net))?'best':''}" style="width:${Math.max(0,v.net)/max*100}%"></div></div></div>`;}document.getElementById('bars').innerHTML=html;
const sorted=[...values].sort((a,b)=>b.net-a.net);document.getElementById('bestName').textContent=sorted[0].name;document.getElementById('bestValue').textContent=fmt(sorted[0].net)+' modeled four-month net value';document.getElementById('comparison').textContent='Modeled difference versus the runner-up: '+fmt(sorted[0].net-sorted[1].net)+'. Selection is sensitive to assumed treatment effect and case availability.';
}
for(const id of ids)document.getElementById(id).addEventListener('input',update);update();
</script></body></html>'''
html=html.replace('__ROWS__',json.dumps(fixed))
(ROOT/'docs/index.html').write_text(html)
print('wrote static docs/index.html',len(html),'chars')
